Definition rinvB (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA c w F', PMR.rloop (PMR.rfuel (PML.srep_chars rep)) (PMRR.rs0 (PML.srep_chars rep)) = tA /\ PMRR.t_code tA = 0 /\ egacc eg (PMRR.t_evs tA) (PMRR.t_al tA) /\ wst M ps c w /\
    PMR.rtail (PMR.rfuel (PML.srep_chars rep)) (PMR.sw (PMRR.t_rs tA)) = PMR.rtail F' (rsof c w gp bof rdst) /\ PMRR.nchunks (rsof c w gp bof rdst) + 1 <= Z.of_nat F'.
