   ((PMRR.t_code tA <> 0 /\ code = PMRR.t_code tA) \/
    (PMRR.t_code tA = 0 /\ exists tB, PMR.rtail (PMR.rfuel (PML.srep_chars rep)) (PMR.sw (PMRR.t_rs tA)) = tB /\
       ((snd tB <> 0 /\ code = snd tB) \/ (snd tB = 0 /\ code = 0 /\ exists c w, wst M ps c w /\ fst tB = rsof c w gp bof rdst)))).
