Definition rinvC0 (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S20|30;!1+=+6$M;R%~R!1+2!1,3|600;!1+4!1+2!1,30$ps;R+5$gp;R+6$rdst;R+6$bof;R+7$eg;R+8!2+9':$tA;R':!2+9+;$rsB;R+;!2+9+<$c;R+<!2+91$w;R1!2+>!3'?#4#3#5!2+>!4'@#:#9#2#1!3+A+;#3!5'B#2#1#8#6#7").
Definition rinvC (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S30|30;!1+=+6!5'B#3#2#9#7#8$M;R%~R!1+2!1,3|600;!1+4!1+2!1,30$ps;R+5$gp;R+6$rdst;R+6$bof;R+7$eg;R+8!2+9':$tA;R':!2+9+;$rsB;R+;!2+9+<$c;R+<!2+91$w;R1!2+9+C$F';R+C!2+>!3'?#5#4#6!2+>!3+A+7!1'D#4,E!2+>!4'@#;#:#3#2!2+>!3+A+6!2'F!1'G!1'H/rep;#4!2'F#12!2'I!2'J!2'J!1'K2!1'L2!1,M,N!1'O#1").
