Definition rinvPC (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  exists tA rsB c w F'' rs, accC0 tA rsB eg /\ PMR.r_eof rsB = false /\ wst M ps c w /\ w <> [] /\
    PMR.refill rs = (rsof c w gp bof rdst, 0) /\ PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = PMR.rcheck (S F'') rs /\ PMRR.nchunks (rsof c w gp bof rdst) + 1 <= Z.of_nat F''.
(* [comment removed for export] *)
Definition rinvC00 (M : mem) (ps : PML.pstate) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
