    (rdst = 2 -> PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = 0) /\
    (rdst = 0 -> PMR.rcheck (PMR.rfuel (PML.srep_chars rep)) rsB = PMR.rcheck F'' (rsof c [] gp bof rdst) /\ PMRR.nchunks (rsof c [] gp bof rdst) + 1 <= Z.of_nat F'').

Lemma ginv_ptrans : forall M M' model model' cr cr' ps ps' gp rdst bof code' g' B eg spc scr eg',
  ginv M model cr ps gp rdst 0 bof g0 B eg ->
  L5C.hpres L LBo spc scr (PMX.W_parx P V E S2) M M' -> sp - SS <= spc - scr -> spc <= sp -> 0 <= scr -> spc mod 16 = 0 ->
  model_but_vm model model' -> hi_heap HI (PML.ps_blocks ps' ++ LBo ++ PMES.g_lbv eg') cr' M' (m_vmmaps model') ->
  PML.parser_at M' P ps' -> PML.wf_ps ps' -> (code' = 0 -> PML.ws_ok ps') -> PML.win_ok M' (LBo ++ PMES.g_lbv eg') ps' -> PML.buf_bound ps' B -> PML.ec_at M' E code' -> PML.ls_ok g' M' ->
