Lemma call_ptransw : forall f pc scr Args Rel, PMW.ptransw L HI PMR.the_rm f PMW.inp_win pc scr Args Rel ->
  forall (fx : FPState) R M model cr ps gp rdst bof B eg spc rc c w,
  PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> wst M ps c w ->
  getr R 1%bv = Z_to_bv 64 rc -> L5.ra_ok rc -> getr R 2%bv = Z_to_bv 64 spc -> getr R 4%bv = Z_to_bv 64 PML.TP ->
  spc mod 16 = 0 -> sp - SS <= spc - scr -> spc <= sp -> 0 <= scr ->
  Args R M P V E ps [] -> (forall ps' code' R', Rel ps ps' code' R' -> code' = 0 -> PML.ws_ok ps') ->
  (forall (fx' : FPState) R' M' model' cr' ps' code' g', PML.fp_ok fx' -> regs_preserved R R' -> ginv M' model' cr' ps' gp rdst code' bof g' B eg ->
      (code' <> 0 -> PML.ps_more ps' = false) -> Rel ps ps' code' R' ->
      (let rr := PMW.rm_step PMR.the_rm f c w in code' = PMW.r_code rr /\ PMW.r_evs rr = [] /\ (code' = 0 -> wst M' ps' (PMW.r_ctrl rr) (PMW.w_after PMR.the_rm rr w))) ->
      TK.samem (fun a => spc <= a < sp) M M' ->
      srealizes RSEGS SCFG (@PML.cfg fx' R' rc M' model') K) ->
