Lemma call_chunkw : forall (fx : FPState) R M model cr ps gp rdst bof B eg spc rc,
  PML.fp_ok fx -> ginv M model cr ps gp rdst 0 bof g0 B eg -> PMS.win_exhausted ps ->
  getr R 1%bv = Z_to_bv 64 rc -> L5.ra_ok rc -> getr R 2%bv = Z_to_bv 64 spc -> getr R 4%bv = Z_to_bv 64 PML.TP -> getr R 10%bv = Z_to_bv 64 Rr -> getr R 11%bv = Z_to_bv 64 E ->
  spc mod 16 = 0 -> sp - SS <= spc - 512 -> spc <= sp ->
  (forall (fx' : FPState) R' M' p k gp' rdst' code' bof' g', PML.fp_ok fx' -> regs_preserved R R' -> ginv M' model cr ps gp' rdst' code' bof' g' B eg ->
      getr R' 10%bv = Z_to_bv 64 p -> getr R' 11%bv = Z_to_bv 64 k -> 0 <= p -> p + k < 2 ^ 64 -> 0 <= k <= 16384 -> (0 < k -> ch <= p /\ p + k <= ch + 16384) ->
      gp <= gp' -> k <= gp' - gp -> (code' = 0 -> k = 0 -> rdst' = 2) -> (rdst' = 0 \/ rdst' = 2) ->
      (rdst = 2 -> k = 0 /\ gp' = gp /\ rdst' = 2 /\ bof' = bof /\ code' = 0) -> (rdst = 0 -> TPSW.chunk_w M' IS rep gp bof ch p k gp' rdst' code' bof') ->
      L5.frame_but ((spc - 512, 512) :: RIXW.Wc Rr IS E ch) M M' -> mem_grows M M' ->
      TK.samem (fun a => spc <= a < sp) M M' ->
      srealizes RSEGS SCFG (@PML.cfg fx' R' rc M' model) K) ->
